import { integer, text } from 'drizzle-orm/sqlite-core';

/** Workcore's conventional string primary key, generated by the application. */
export function idColumn(name = 'id') {
  return { id: text(name).primaryKey() };
}

/** Epoch-millisecond timestamps; updatedAt is refreshed by Drizzle writes. */
export function timestampColumns() {
  const now = () => Date.now();
  return {
    createdAt: integer('created_at').notNull().$defaultFn(now),
    updatedAt: integer('updated_at').notNull().$defaultFn(now).$onUpdateFn(now),
  };
}

/** Optional optimistic concurrency token for editable records. */
export function versionColumn(name = 'version') {
  return { version: integer(name).notNull().default(1) };
}
